// npm install express express-session express-rate-limit bcrypt
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 24 * 60 * 60 * 1000,
  },
}));

// Replace with your database: username -> { id, username, passwordHash }.
const users = new Map();

const BCRYPT_ROUNDS = 12;
// Compared against when the user does not exist, so response time does not reveal valid usernames.
const DUMMY_HASH = bcrypt.hashSync('dummy', BCRYPT_ROUNDS);

// Allows 5 failed attempts per IP per 15 minutes; successful logins do not count.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed login attempts. Try again later.' },
});

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || password.length < 8) {
    return res.status(400).json({ error: 'Username and a password of at least 8 characters are required.' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'Username is taken.' });
  }
  const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);
  users.set(username, { id: users.size + 1, username, passwordHash });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Username and password are required.' });
  }
  const user = users.get(username);
  const ok = await bcrypt.compare(password, user ? user.passwordHash : DUMMY_HASH);
  if (!user || !ok) {
    return res.status(401).json({ error: 'Invalid username or password.' });
  }
  // Issue a fresh session ID on login to prevent session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not logged in.' });
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

app.listen(3000);
```

I have not run this, and it assumes Express 5, which forwards errors from async handlers; on Express 4 wrap the async routes in try/catch.

Security warning: the `users` Map, the default session store and the limiter's counters all live in process memory, so before production swap in a database, a session store such as `connect-redis`, and a shared limiter store.

Security warning: the limiter is keyed by IP only, so add a per-username counter if distributed guessing against one account matters, and set `app.set('trust proxy', 1)` behind a reverse proxy or every client shares one IP and the secure cookie is never set.

CSRF protection is left out because `sameSite: 'lax'` covers JSON POSTs; add a CSRF token if you accept form posts or loosen that cookie setting.
